import fs from 'node:fs/promises';
import path from 'node:path';
import { config } from './config.js';

const root = path.resolve(config.storageDir);

// Paths are built only from UUIDs generated by the server, never from user input.
export function orderFilePath(shopId, orderId) {
  return path.join(root, 'orders', shopId, `${orderId}.pdf`);
}

export async function saveFile(filePath, buffer) {
  await fs.mkdir(path.dirname(filePath), { recursive: true });
  await fs.writeFile(filePath, buffer);
}

export async function removeFile(filePath) {
  try {
    await fs.unlink(filePath);
  } catch (e) {
    if (e.code !== 'ENOENT') throw e;
  }
}

export async function removeShopFiles(shopId) {
  await fs.rm(path.join(root, 'orders', shopId), { recursive: true, force: true });
}
